/**
 * @summary List open venue reports for moderator review
 */
export const getListVenueReportsForReviewUrl = (
  params?: ListVenueReportsForReviewParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/feedback/admin/reports?${stringifiedParams}`
    : `/api/feedback/admin/reports`;
};

